// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public { c = new PuttyV2("", 0, address(this)); }

    // EIP-1271 hook: order.maker is this contract, so signature checks pass
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    // baseAsset hook: c low-level calls transferFrom on baseAsset (== address(this))
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function testFuzz_property(uint256 duration, bool isCall, uint256 nonce) public {
        duration = bound(duration, 1, 10_000 days - 1);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: isCall,
            isLong: false,
            baseAsset: address(this),
            strike: 0,
            premium: 0,
            duration: duration,
            expiration: block.timestamp + 10_000 days + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        uint256 longPositionId = uint256(c.hashOppositeOrder(order));

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory sig = new bytes(0);

        c.fillOrder(order, sig, floorAssetTokenIds);

        // Rule: a short fill records the expiration on the LONG position id.
        assertTrue(
            c.positionExpirations(longPositionId) == block.timestamp + duration,
            "short fill must set expiration under the long position id"
        );
    }
}
